// generar_309_canas_desaparecen_y_selector_mes_calendario.js
// CHIQUI Entre Señales — Canas/ojos desaparecen + selector de mes en calendario
//
// Dos ajustes:
//
// 1. REGISTRO DIARIO — cambios de edad desaparecen al registrarse.
//    Antes, al registrar "primeras canas" u "ojos más opacos", el bloque
//    se quedaba mostrando "ya registrado" con un botón Corregir. Ahora,
//    una vez registrado, el bloque DESAPARECE del registro diario (queda
//    guardado en la línea de tiempo del Perfil). Más limpio y coherente
//    con los momentos únicos.
//
// 2. CALENDARIO — selector de mes/año para saltar directo.
//    Antes, para registrar un momento antiguo (ej. una esterilización de
//    hace años) había que retroceder mes a mes con las flechas ‹ ›.
//    Ahora el título del mes ("Junio 2026 ▼") es un botón: al tocarlo se
//    abre un selector con dropdowns de mes y año (hasta 30 años atrás)
//    para ir directo a cualquier fecha en un toque.
//
// No hay SQL.
//
// Uso:
//   node generar_309_canas_desaparecen_y_selector_mes_calendario.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: "app/registro-diario/page.tsx",
    base64: ""
  },
  {
    ruta: "app/calendario/page.tsx",
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 2 archivos escritos. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
